import React, { useState } from "react";
import "../styles/table.css";
import { mockData } from "../mockdata";

const Table = () => {
  const [data, setData] = useState(mockData);
  const [sortConfig, setSortConfig] = useState({ key: null, direction: "ascending" });

   const DuplicateIcon = () => (
  <button className="icon-btn duplicate" title="Duplicate">📄</button>
);

 const EditIcon = () => (
  <button className="icon-btn edit" title="Edit">✏️</button>
);

 const DeleteIcon = () => (
  <button className="icon-btn delete" title="Delete">🗑️</button>
);


  const requestSort = (key) => {
    let direction = sortConfig.key === key && sortConfig.direction === "ascending" ? "descending" : "ascending";
    setSortConfig({ key, direction });

    setData([...data].sort((a, b) => (a[key] < b[key] ? (direction === "ascending" ? -1 : 1) : a[key] > b[key] ? (direction === "ascending" ? 1 : -1) : 0)));
  };

  return (
    <div className="table-container">
      <table className="styled-table">
        <thead>
          <tr>
            <th>#</th>
            <th onClick={() => requestSort("name")}>Name</th>
            <th onClick={() => requestSort("category")}>Category</th>
            <th onClick={() => requestSort("createdOn")}>Created On</th>
            <th>Duplicate</th>
            <th>Edit</th>
            <th>Delete</th>
          </tr>
        </thead>
        <tbody>
          {data.map((row, index) => (
            <tr key={row.id}>
              <td>{index + 1}</td>
              <td>{row.name}</td>
              <td>{row.category}</td>
              <td>{row.createdOn}</td>
              <td><DuplicateIcon /></td>
              <td><EditIcon /></td>
              <td><DeleteIcon /></td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default Table;
